struct W { fd: i32 }
function (w: W) put(s: string): W { return w; }
function (w: W) try_put(s: string): Result[W, string] { return Ok(w); }
function (own w: W) close(): i32 { return w.fd; }
function run(): i32 { let o = W { fd: 1 }; o = o.put("a"); o = o.put("b"); return o.close(); }
function main(): i32 { return run() - 1; }

struct W { fd: i32 }
function (w: W) try_put(s: string): Result[W, string] { return Ok(w); }
function (own w: W) close(): i32 { return w.fd; }
function keep(r: Result[W, string], fallback: W): W { match (r) { Ok(w) => { return w; }, Err(_) => { return fallback; } } }
function run(): i32 { let b = W { fd: 1 }; b = keep(b.try_put("a"), b); return b.close(); }
function main(): i32 { return run() - 1; }

struct W { fd: i32 }
function (w: W) put(s: string): W { return w; }
function (w: W) try_put(s: string): Result[W, string] { return Ok(w); }
function (own w: W) close(): i32 { return w.fd; }
function run(): i32 { let buf = W { fd: 1 }; let i = 0; while (i < 2) { match (buf.try_put("a")) { Ok(w) => { buf = w; }, Err(_) => { return 9; } } i += 1; } return buf.close(); }
function main(): i32 { return run() - 1; }

struct W { fd: i32 }
function (w: W) put(s: string): W { return w; }
function (w: W) try_put(s: string): Result[W, string] { return Ok(w); }
function (own w: W) close(): i32 { return w.fd; }
struct Out { w: W, n: i32 }
function settle(own o: Out, own written: Result[W, string]): Out { match (written) { Ok(w) => { return Out { ...o, w: w }; }, Err(_) => {} } return o; }
function put(own o: Out, s: string): Out { let written = o.w.try_put(s); return settle(o, written); }
function main(): i32 { let o = put(Out { w: W { fd: 1 }, n: 0 }, "a"); return o.w.close() - 1; }

